
///////////////////////////////////////////////////////////////////////////////////////////////////
// module : mc0_alc_mc_top
///////////////////////////////////////////////////////////////////////////////////////////////////

`timescale 1ps/1ps

//`include "ph1p_mis_define.vh"
`define MC0_DRAM_DDR3
`define MC0_DDR3_2G
`define MC0_DDR3_X16
`define MC0_DDR3_800E
`define PH1P100
`define MC0_MIS_AXI
`define PH1P_VCCIO_1V35
`define DHI_DATA_FORMAT_BYTE


module mc0_alc_mc_top #(
    parameter tCK                  = 1876    ,
    parameter DRAM_TYPE            = "DDR3"  ,
    parameter DX_NUM               = 2       ,
    parameter CWL                  = 8       ,
    parameter BG_WIDTH             = 0       ,
    parameter BA_WIDTH             = 3       ,
    parameter ROW_WIDTH            = 13      ,
    parameter COL_WIDTH            = 10      ,

    parameter MC_ECC               = "ON"   ,
    parameter MC_ADDR_MAP          = "ROW_COL_BANK",
    parameter MC_REORDER           = "STRICT",

    parameter MC_ADDR_WIDTH        = BG_WIDTH + BA_WIDTH + ROW_WIDTH + COL_WIDTH,
    parameter MC_DATA_WIDTH        = (MC_ECC == "ON") ? (DX_NUM-1)*8*8 : DX_NUM*8*8,
    parameter MC_MASK_WIDTH        = (MC_ECC == "ON") ? (DX_NUM-1)*8   : DX_NUM*8  
) (
    // System input
    input                                  clk                ,
    input                                  rst                ,
    input                                  ddrphy_rdy         ,

    //User Interface
    input        [MC_ADDR_WIDTH-1 : 0]     paxi_awaddr        ,
    input                                  paxi_awvalid       ,
    output                                 paxi_awready       ,

    input        [MC_DATA_WIDTH-1 : 0]     paxi_wdata         ,
    input        [MC_MASK_WIDTH-1 : 0]     paxi_wstrb         ,
    input                                  paxi_wvalid        ,
    input                                  paxi_wlast         ,
    output                                 paxi_wready        ,

    // Write Response Port
    output       [              1 : 0]     paxi_bresp         ,
    output                                 paxi_bvalid        ,
    input                                  paxi_bready        ,

    // Read Address Ports
    input        [MC_ADDR_WIDTH-1 : 0]     paxi_araddr        ,
    input                                  paxi_arvalid       ,
    output                                 paxi_arready       ,

    // Read Data Ports
    output       [MC_DATA_WIDTH-1 : 0]     paxi_rdata         ,
    output                                 paxi_rlast         ,
    output                                 paxi_rvalid        ,
    input                                  paxi_rready        ,

    // User Refresh
    input        [              1 : 0]     usr_ref_type       ,
    input                                  usr_ref_req        ,
    output                                 usr_ref_ack        ,

    //ecc error signals
    output       [              7 : 0]     ecc_single         ,
    output       [              7 : 0]     ecc_multiple       ,

    // ddrphy host interface
    output                                 dhi_cmd_vld_p0     ,
    output                                 dhi_cmd_vld_p1     ,
    output                                 dhi_cmd_vld_p2     ,
    output                                 dhi_cmd_vld_p3     ,
    output       [           32-1 : 0]     dhi_cmd_code_p0    ,
    output       [           32-1 : 0]     dhi_cmd_code_p1    ,
    output       [           32-1 : 0]     dhi_cmd_code_p2    ,
    output       [           32-1 : 0]     dhi_cmd_code_p3    ,

    input                                  dhi_rdata_vld      ,
    input        [   DX_NUM*8*8-1 : 0]     dhi_rdata          ,

    input                                  dhi_wdata_en       ,
    output       [   DX_NUM*8*8-1 : 0]     dhi_wdata          ,
    output       [   DX_NUM*8  -1 : 0]     dhi_wmask          
);

///////////////////////////////////////////////////////////////////////////////////////////////////
//  Local Parameter Definition
///////////////////////////////////////////////////////////////////////////////////////////////////
localparam  ECC_OREG    = 1;

localparam  PHY_DX_NUM  = DX_NUM;
localparam  USR_DX_NUM  = (MC_ECC == "ON") ? (DX_NUM-1) : DX_NUM;

localparam  CS_WIDTH    = 1;
localparam  CKE_WIDTH   = 1;
localparam  ODT_WIDTH   = 1;
localparam  ADDR_WIDTH  = (DRAM_TYPE == "DDR4") ? 17 : ROW_WIDTH;

localparam  DBAW_R      = 5;
localparam  DBAW_W      = 4;

////////////////////////////////////////////////////////////////
// DDR SpeedBin
////////////////////////////////////////////////////////////////
//`include "ddr_common.vh"

///////////////////////////////////////////////////////////////////////////////////////////////////
localparam real tREFI = 7_800_000;
localparam real tWR   = 15_000;
///////////////////////////////////////////////////////////////////////////////////////////////////
`ifdef MC0_DDR3_512M
localparam real tRFC = 90_000;
`elsif MC0_DDR3_1G
localparam real tRFC = 110_000;
`elsif MC0_DDR3_2G
localparam real tRFC = 160_000;
`elsif MC0_DDR3_4G
localparam real tRFC = 260_000;
`elsif MC0_DDR3_8G
localparam real tRFC = 350_000;
`endif

///////////////////////////////////////////////////////////////////////////////////////////////////
`ifdef MC0_DDR3_800D
localparam CL   = 5;
localparam real tRC  = 50_000;
`elsif MC0_DDR3_800E
localparam CL   = 6;
localparam real tRC  = 52_500;
`elsif MC0_DDR3_1066E
localparam CL   = 6;
localparam real tRC  = 48_750;
`elsif MC0_DDR3_1066F
