localparam CL   = 8;
localparam real tRC  = 52_500;
`elsif MC0_DDR3_1333F
localparam CL   = 7;
localparam real tRC  = 46_500;
`elsif MC0_DDR3_1333G
localparam CL   = 8;
localparam real tRC  = 48_000;
`elsif MC0_DDR3_1333H
localparam CL   = 9;
localparam real tRC  = 49_500;
`elsif MC0_DDR3_1333J
localparam CL   = 10;
localparam real tRC  = 51_000;
`elsif MC0_DDR3_1600G
localparam CL   = 8;
localparam real tRC  = 45_000;
`elsif MC0_DDR3_1600H
localparam CL   = 9;
localparam real tRC  = 46_250;
`elsif MC0_DDR3_1600J
localparam CL   = 10;
localparam real tRC  = 47_500;
`elsif MC0_DDR3_1600K
localparam CL   = 11;
localparam real tRC  = 48_750;
`elsif MC0_DDR3_1866J
localparam CL   = 10;
localparam real tRC  = 44_700;
`elsif MC0_DDR3_1866K
localparam CL   = 11;
localparam real tRC  = 45_770;
`elsif MC0_DDR3_1866L
localparam CL   = 12;
localparam real tRC  = 46_840;
`elsif MC0_DDR3_1866M
localparam CL   = 13;
localparam real tRC  = 47_910;
`endif

///////////////////////////////////////////////////////////////////////////////////////////////////


//`include "ddr_speedbin.vh"

// min in tCK
localparam nRTP_min  = 4;
localparam nWTR_min  = 4;
localparam nZQCS_min = 64;
localparam nXS_min   = 5;
localparam nRRD_min  = 4;
localparam nCCD      = 4;

// min in ps
localparam real tRTP_min  =  7_500;
localparam real tWTR_min  =  7_500;
localparam real tZQCS_min = 80_000;
localparam real tRAS      = 37_500;
localparam real tXS_min   = tRFC+10_000;

`ifdef MC0_DDR3_8G
localparam real tRRD_min  = 10_000;
localparam real tFAW      = 50_000;
`else // MC0_DDR3_512M DDR3_1G DDR3_2G DDR3_4G
`ifdef MC0_DDR3_X16
localparam real tRRD_min  = 10_000;
localparam real tFAW      = 50_000;
`else // MC0_DDR3_X4 DDR3_X8
localparam real tRRD_min  = 10_000;
localparam real tFAW      = 40_000;
`endif
`endif



`ifdef MC0_DRAM_DDR4
localparam integer nRCD   = CL;
localparam integer nRP    = CL;
localparam integer nRAS   = $ceil(tRAS/tCK);
localparam integer nRC    = $ceil(tRC /tCK);
localparam integer nCCD_S = 4;
localparam integer nCCD_L = (nCCD_L_min > $ceil(tCCD_L_min/tCK)) ? nCCD_L_min : $ceil(tCCD_L_min/tCK);
localparam integer nRRD_L = (nRRD_L_min > $ceil(tRRD_L_min/tCK)) ? nRRD_L_min : $ceil(tRRD_L_min/tCK);
localparam integer nRRD_S = (nRRD_S_min > $ceil(tRRD_S_min/tCK)) ? nRRD_S_min : $ceil(tRRD_S_min/tCK);
localparam integer nFAW   = (nFAW_min   > $ceil(tFAW_min  /tCK)) ? nFAW_min   : $ceil(tFAW_min  /tCK);
localparam integer nWTR_S = (nWTR_S_min > $ceil(tWTR_S_min/tCK)) ? nWTR_S_min : $ceil(tWTR_S_min/tCK);
localparam integer nWTR_L = (nWTR_L_min > $ceil(tWTR_L_min/tCK)) ? nWTR_L_min : $ceil(tWTR_L_min/tCK);
localparam integer nRTP   = (nRTP_min   > $ceil(tRTP_min  /tCK)) ? nRTP_min   : $ceil(tRTP_min  /tCK);
localparam integer nMOD   = (nMOD_min   > $ceil(tMOD_min  /tCK)) ? nMOD_min   : $ceil(tMOD_min  /tCK);
localparam integer nWR    = (10         > $ceil(tWR       /tCK)) ? 10         : $ceil(tWR       /tCK);
localparam integer nMRD   = $ceil(tMRD /tCK);
localparam integer nREFI  = $ceil(tREFI/tCK);
localparam integer nRFC   = $ceil(tRFC1/tCK);
localparam nRTW = CL + 4 - CWL + 2; // RL + BL/2 - WL + 2tCK + X
`elsif MC0_DRAM_DDR3
localparam integer nRCD  = CL;
localparam integer nRP   = CL;
localparam integer nREFI = $ceil(tREFI/tCK);
localparam integer nFAW  = $ceil(tFAW /tCK);
localparam integer nRAS  = $ceil(tRAS /tCK);
localparam integer nRFC  = $ceil(tRFC /tCK);
localparam integer nWR   = (5         > $ceil(tWR      /tCK)) ? 5         : $ceil(tWR      /tCK);
localparam integer nRTP  = (nRTP_min  > $ceil(tRTP_min /tCK)) ? nRTP_min  : $ceil(tRTP_min /tCK);
localparam integer nWTR  = (nWTR_min  > $ceil(tWTR_min /tCK)) ? nWTR_min  : $ceil(tWTR_min /tCK);
localparam integer nRRD  = (nRRD_min  > $ceil(tRRD_min /tCK)) ? nRRD_min  : $ceil(tRRD_min /tCK);
localparam integer nZQCS = (nZQCS_min > $ceil(tZQCS_min/tCK)) ? nZQCS_min : $ceil(tZQCS_min/tCK);
localparam integer nXS   = (nXS_min   > $ceil(tXS_min  /tCK)) ? nXS_min   : $ceil(tXS_min  /tCK);
localparam nRTW = CL + nCCD + 2 - CWL; // RL + tCCD + 2tCK - WL + X
`elsif MC0_DRAM_DDR2
localparam integer nRCD  = CL;
localparam integer nRP   = CL;
localparam integer nREFI = $ceil(tREFI/tCK);
localparam integer nFAW  = $ceil(tFAW /tCK);
localparam integer nRAS  = $ceil(tRAS /tCK);
localparam integer nRFC  = $ceil(tRFC /tCK);
localparam integer nRRD  = $ceil(tRRD /tCK);
localparam integer nWR   = $ceil(tWR  /tCK);
localparam nRTW = 6; // BL=4 : 4tCK; BL=8 : 6tCK
`endif

